const fs=require("fs"),path=require("path");function searchInFiles(s){fs.readdirSync(s).forEach(t=>{const e=path.join(s,t);if(fs.statSync(e).isDirectory()&&"node_modules"!==t&&".git"!==t&&"dist"!==t)searchInFiles(e);else if(t.endsWith(".js")||t.endsWith(".json")||t.endsWith(".html"))try{const s=fs.readFileSync(e,"utf8");s.split("\n").forEach((s,t)=>{/biz_catering|intent-BIZ|OPT_BIZ|catering/i.test(s)&&console.log(`${e}:${t+1}: ${s.trim()}`)})}catch(s){}})}searchInFiles(".");